1	/****************************************************************************
2	 * arch/risc-v/src/common/espressif/esp_jpeg_enc.c
3	 * ESP32-P4 Hardware JPEG Encoder in V4L2 M2M framework
4	 *
5	 * Uses the esp-hal-3rdparty JPEG HAL (jpeg_new_encoder_engine /
6	 * jpeg_encoder_process / jpeg_del_encoder_engine) to turn one RGB565
7	 * frame queued on the OUTPUT queue into a JPEG bitstream on the CAPTURE
8	 * queue.  Encoding is triggered from the *_available() callbacks, which
9	 * the v4l2_m2m core invokes after every VIDIOC_QBUF.
10	 *
11	 * SPDX-License-Identifier: Apache-2.0
12	 ****************************************************************************/
13	
14	#include <nuttx/config.h>
15	#include <stdio.h>
16	#include <string.h>
17	#include <debug.h>
18	#include <errno.h>
19	#include <sys/param.h>
20	
21	#include <nuttx/kmalloc.h>
22	#include <nuttx/mutex.h>
23	#include <nuttx/video/v4l2_m2m.h>
24	
25	#include "driver/jpeg_encode.h"
26	
27	/* Polled markers use the USB-Serial-JTAG TX FIFO directly.  To avoid a race
28	 * with the console ISR (which flushes the printf xmit buffer via the same
29	 * FIFO + txfifo_flush and drops concurrently-written bytes), the console TX
30	 * interrupt is masked for the duration of jpeg_new_encoder_engine so the
31	 * markers own the FIFO exclusively.  See esp_usbserial_write()/esp_send().
32	 */
33	#include "esp_usbserial.h"
34	
35	#define JPEG_DEF_WIDTH    1024
36	#define JPEG_DEF_HEIGHT   600
37	#define JPEG_MAX_BUF      6
38	#define JPEG_QUALITY      80
39	
40	struct esp_jpeg_dev_s
41	{
42	  struct v4l2_format  out_fmt;
43	  struct v4l2_format  cap_fmt;
44	  jpeg_encoder_handle_t engine;
45	  FAR void *cookie;              /* v4l2_m2m codec_file_t, for codec_*_buf() */
46	  size_t  encoded;
47	};
48	
49	static int jpeg_cap_enum_fmt(FAR void *p, FAR struct v4l2_fmtdesc *f)
50	{ if (f->index > 0) return -EINVAL; f->pixelformat = V4L2_PIX_FMT_JPEG;
51	  f->type = V4L2_BUF_TYPE_VIDEO_CAPTURE; return OK; }
52	
53	static int jpeg_out_enum_fmt(FAR void *p, FAR struct v4l2_fmtdesc *f)
54	{ if (f->index > 0) return -EINVAL; f->pixelformat = V4L2_PIX_FMT_RGB565;
55	  f->type = V4L2_BUF_TYPE_VIDEO_OUTPUT; return OK; }
56	
57	static int jpeg_cap_g_fmt(FAR void *p, FAR struct v4l2_format *f)
58	{ memcpy(f, &((struct esp_jpeg_dev_s *)p)->cap_fmt, sizeof(*f)); return OK; }
59	
60	static int jpeg_out_g_fmt(FAR void *p, FAR struct v4l2_format *f)
61	{ memcpy(f, &((struct esp_jpeg_dev_s *)p)->out_fmt, sizeof(*f)); return OK; }
62	
63	static int jpeg_cap_s_fmt(FAR void *p, FAR struct v4l2_format *f)
64	{ struct esp_jpeg_dev_s *d = p;
65	  if (f->fmt.pix.pixelformat != V4L2_PIX_FMT_JPEG) return -EINVAL;
66	  f->fmt.pix.width  = d->out_fmt.fmt.pix.width;
67	  f->fmt.pix.height = d->out_fmt.fmt.pix.height;
68	  f->fmt.pix.sizeimage = d->out_fmt.fmt.pix.sizeimage;
69	  memcpy(&d->cap_fmt, f, sizeof(*f)); return OK; }
70	
71	static int jpeg_out_s_fmt(FAR void *p, FAR struct v4l2_format *f)
72	{ struct esp_jpeg_dev_s *d = p;
73	  if (f->fmt.pix.pixelformat != V4L2_PIX_FMT_RGB565) return -EINVAL;
74	  f->fmt.pix.width  = CLAMP(f->fmt.pix.width,  16, 1024);
75	  f->fmt.pix.height = CLAMP(f->fmt.pix.height, 16, 768);
76	  f->fmt.pix.sizeimage = f->fmt.pix.width * f->fmt.pix.height * 2;
77	  memcpy(&d->out_fmt, f, sizeof(*f)); return OK; }
78	
79	static size_t jpeg_cap_bufsize(FAR void *p)
80	{ return ((struct esp_jpeg_dev_s *)p)->out_fmt.fmt.pix.sizeimage; }
81	
82	static size_t jpeg_out_bufsize(FAR void *p)
83	{ return ((struct esp_jpeg_dev_s *)p)->out_fmt.fmt.pix.sizeimage; }
84	
85	static size_t jpeg_cap_bufcnt(FAR void *p) { return 4; }
86	static size_t jpeg_out_bufcnt(FAR void *p) { return 4; }
87	
88	static FAR void *jpeg_alloc(FAR void *p, size_t sz) { return kmm_malloc(sz); }
89	static void jpeg_free(FAR void *p, FAR void *a) { kmm_free(a); }
90	
91	/****************************************************************************
92	 * Name: jpeg_encode_one
93	 *
94	 * Description:
95	 *   Pull one RGB565 frame from the OUTPUT queue, encode it with the JPEG
96	 *   HAL, and push the resulting bitstream into the CAPTURE queue.
97	 *   Safe to call from either *_available() callback (the v4l2_m2m core
98	 *   calls these after each QBUF on the respective queue); no-ops when a
99	 *   frame or a capture buffer is missing.
100	 *
101	 ****************************************************************************/
102	
103	static int jpeg_encode_one(FAR void *priv)
104	{
105	  struct esp_jpeg_dev_s *d = priv;
106	  FAR struct v4l2_buffer *in;
107	  FAR struct v4l2_buffer *cap;
108	  jpeg_encode_cfg_t cfg;
109	  uint32_t out_sz = 0;
110	  esp_err_t err;
111	
112	  if (d->engine == NULL)
113	    {
114	      return 0;
115	    }
116	
117	  in = codec_output_get_buf(d->cookie);
118	  if (in == NULL)
119	    {
120	      return 0;
121	    }
122	
123	  dbg_putc('p');               /* jpeg_encode_one: about to get capture buf */
124	  cap = codec_capture_get_buf(d->cookie);
125	  if (cap == NULL)
126	    {
127	      codec_output_put_buf(d->cookie, in);
128	      return 0;
129	    }
130	
131	  memset(&cfg, 0, sizeof(cfg));
132	  cfg.width         = d->out_fmt.fmt.pix.width;
133	  cfg.height        = d->out_fmt.fmt.pix.height;
134	  cfg.src_type      = JPEG_ENCODE_IN_FORMAT_RGB565;
135	  cfg.sub_sample    = JPEG_DOWN_SAMPLING_YUV420;
136	  cfg.image_quality = JPEG_QUALITY;
137	
138	  dbg_putc('q');               /* about to call jpeg_encoder_process */
139	  err = jpeg_encoder_process(d->engine, &cfg,
140	                             (FAR const uint8_t *)in->m.vaddr,
141	                             in->length,
142	                             (FAR uint8_t *)cap->m.vaddr,
143	                             cap->length,
144	                             &out_sz);
145	  dbg_putc('r');               /* jpeg_encoder_process returned */
146	  if (err != ESP_OK)
147	    {
148	      vwarn("jpeg encode failed: %d\n", err);
149	      cap->bytesused = 0;
150	      codec_capture_put_buf(d->cookie, cap);
151	      codec_output_put_buf(d->cookie, in);
152	      return 0;
153	    }
154	
155	  vinfo("encoded %u x %u RGB565 -> %u bytes JPEG\n",
156	        cfg.width, cfg.height, (unsigned int)out_sz);
157	  cap->bytesused = out_sz;
158	  d->encoded = out_sz;
159	  codec_capture_put_buf(d->cookie, cap);
160	  codec_output_put_buf(d->cookie, in);
161	  return 0;
162	}
163	
164	static int jpeg_open(FAR void *cookie, FAR void **priv)
165	{
166	  struct esp_jpeg_dev_s *d;
167	  dbg_putc('V');               /* jpeg_open entered */
168	  d = kmm_zalloc(sizeof(*d));
169	  jpeg_encode_engine_cfg_t ecfg;
170	  esp_err_t err;
171	
172	  if (d == NULL)
173	    {
174	      return -ENOMEM;
175	    }
176	
177	  d->cookie = cookie;
178	  d->out_fmt.type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
179	  d->out_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
180	  d->out_fmt.fmt.pix.width  = JPEG_DEF_WIDTH;
181	  d->out_fmt.fmt.pix.height = JPEG_DEF_HEIGHT;
182	  d->out_fmt.fmt.pix.sizeimage = JPEG_DEF_WIDTH * JPEG_DEF_HEIGHT * 2;
183	  d->cap_fmt = d->out_fmt;
184	  d->cap_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
185	
186	  /* Create the ESP-HAL JPEG encoder engine.  One engine per open file;
187	   * the HAL reference-counts the underlying codec handle internally. */
188	
189	  memset(&ecfg, 0, sizeof(ecfg));
190	  ecfg.intr_priority = 0;   /* driver picks a default */
