import socket, time

def oc_cmd(cmd, timeout=3):
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.settimeout(timeout)
    s.connect(('localhost', 4444))
    time.sleep(0.2)
    s.recv(4096)  # banner
    s.send((cmd + '\n').encode())
    time.sleep(0.5)
    result = b''
    try:
        while True:
            chunk = s.recv(4096)
            if not chunk:
                break
            result += chunk
            time.sleep(0.1)
    except socket.timeout:
        pass
    s.close()
    return result.decode(errors='replace')

