1	/****************************************************************************
2	 * apps/examples/jpegenc/jpegenc_main.c
3	 *
4	 * Encode one RGB565 frame to JPEG using the ESP32-P4 hardware JPEG encoder
5	 * (/dev/video1, V4L2 M2M).
6	 *
7	 * Input:  /data/capture.rgb565  (1024x600 RGB565, from camcap)
8	 * Output: /data/capture.jpg
9	 *
10	 * SPDX-License-Identifier: Apache-2.0
11	 ****************************************************************************/
12	
13	#include <syslog.h>
14	#include <nuttx/config.h>
15	#include <stdio.h>
16	#include <stdlib.h>
17	#include <string.h>
18	#include <fcntl.h>
19	#include <unistd.h>
20	#include <errno.h>
21	#include <malloc.h>
22	#include <poll.h>
23	#include <sys/ioctl.h>
24	#include <sys/stat.h>
25	#include <sys/videoio.h>
26	
27	/* RAM debug markers (digits, distinct from arch markers W C i s b e P z c D
28	 * d m n o q E X).  dbg_mark_char() records to the app-only marker address
29	 * (0x5010ffe0) even when the USB console is wedged; the esp_bringup boot
30	 * dump reads it back after a warm reset.  Boot's dbg_putc() markers live at
31	 * 0x5010fff0 and would clobber this address, hence the separation.
32	 */
33	
34	extern void dbg_mark_char(int ch);
35	#define MARK(c) dbg_mark_char(c)
36	
37	/* Print the previous run's last RAM debug marker (survives warm reset). */
38	
39	#define PREV_MARK_ADDR ((volatile uint32_t *)0x5010ffe0)
40	
41	#define M2M_DEV     "/dev/video1"
42	#define IN_FILE     "/tmp/capture.rgb565"
43	#define OUT_FILE    "/tmp/capture.jpg"
44	#define W           1024
45	#define H           600
46	
47	/* RGB565 input frame size (2 bytes/pixel) */
48	#define OUT_SIZE    (W * H * 2)
49	/* JPEG output buffer: driver uses W*H for capture sizeimage, but allow slack */
50	#define CAP_SIZE    (W * H * 2)
51	
52	static int xioctl(int fd, int req, void *arg)
53	{
54	  int r;
55	  do { r = ioctl(fd, req, arg); } while (r == -1 && errno == EINTR);
56	  return r;
57	}
58	
59	int main(int argc, char *argv[])
60	{
61	  int fd = -1, infd = -1, outfd = -1;
62	  int ret = EXIT_FAILURE;
63	  struct v4l2_format fmt;
64	  struct v4l2_requestbuffers req;
65	  struct v4l2_buffer buf;
66	  void *inbuf = NULL;
67	  void *capbuf = NULL;
68	  enum v4l2_buf_type out_type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
69	  enum v4l2_buf_type cap_type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
70	  size_t n;
71	
72	  MARK('@');                     /* main entry */
73	  MARK('A');                     /* before 1st printf */
74	  uint32_t prev = *PREV_MARK_ADDR;
75	  MARK('B');                     /* after skipped printf */
76	  dbg_mark_char('#');            /* RAM-write self-test: expect 0x23 */
77	  MARK('C');                     /* after dbg_mark */
78	  /* fflush(stdout); */
79	  MARK('a');                     /* fflush done, about to allocate input */
80	
81	  /* Generate the RGB565 input frame in memory (skip file I/O for now) */
82	
83	  inbuf = memalign(64, OUT_SIZE);
84	  MARK('b');                     /* input memalign done */
85	  if (!inbuf)
86	    { /* printf("ERROR: memalign input\n"); */ goto out; }
87	  printf("  inbuf @ %p (%d bytes)\n", inbuf, OUT_SIZE);
88	  /* fflush(stdout); */
89	
90	  {
91	    uint8_t *p = (uint8_t *)inbuf;
92	    size_t i;
93	    for (i = 0; i < OUT_SIZE; i++)
94	      {
95	        p[i] = (uint8_t)(i * 31 + (i >> 8));
96	      }
97	  }
98	  n = OUT_SIZE;
99	  MARK('f');                     /* input filled in memory */
100	  printf("  [marker@f] 0x%02x\n", (int)(*PREV_MARK_ADDR));
101	  /* fflush(stdout); */
102	  *PREV_MARK_ADDR = 0xAA;        /* sentinel: survive warm reset */
103	  printf("  [sentinel] 0x%02x\n", (int)(*PREV_MARK_ADDR));
104	  /* fflush(stdout); */
105	  printf("  generated %ld bytes in memory\n", (long)n);
106	  /* fflush(stdout); */
107	
108	  /* Open M2M device */
109	
110	  MARK('0'); /* about to open M2M device */
111	  fd = open(M2M_DEV, O_RDWR, 0);
112	  if (fd < 0)
113	    { /* printf("ERROR: open %s: %d\n", M2M_DEV, errno); */ goto out; }
114	  MARK('1'); /* device open */
115	
116	  /* Set OUTPUT queue format: RGB565 */
117	
118	  memset(&fmt, 0, sizeof(fmt));
119	  fmt.type                = out_type;
120	  fmt.fmt.pix.width       = W;
121	  fmt.fmt.pix.height      = H;
122	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
123	  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
124	  if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0)
125	    { /* printf("ERROR: OUTPUT S_FMT: %d\n", errno); */ goto out; }
126	  /* printf("  OUTPUT fmt: %ux%u sizeimage=%u\n",
127	         (unsigned int)fmt.fmt.pix.width, (unsigned int)fmt.fmt.pix.height,
128	         (unsigned int)fmt.fmt.pix.sizeimage); */
129	  /* fflush(stdout); */
130	  MARK('2'); /* output S_FMT ok */
131	
132	  /* Set CAPTURE queue format: JPEG */
133	
134	  memset(&fmt, 0, sizeof(fmt));
135	  fmt.type                = cap_type;
136	  fmt.fmt.pix.width       = W;
137	  fmt.fmt.pix.height      = H;
138	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
139	  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
140	  if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0)
141	    { /* printf("ERROR: CAPTURE S_FMT: %d\n", errno); */ goto out; }
142	  /* printf("  CAPTURE fmt: %ux%u sizeimage=%u\n",
143	         (unsigned int)fmt.fmt.pix.width, (unsigned int)fmt.fmt.pix.height,
144	         (unsigned int)fmt.fmt.pix.sizeimage); */
145	  /* fflush(stdout); */
146	  MARK('3'); /* capture S_FMT ok */
147	
148	  /* Request buffers on both queues (USERPTR) */
149	
150	  memset(&req, 0, sizeof(req));
151	  req.type   = out_type;
152	  req.memory = V4L2_MEMORY_USERPTR;
153	  req.count  = 2;
154	  if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0)
155	    { /* printf("ERROR: OUTPUT REQBUFS: %d\n", errno); */ goto out; }
156	
157	  memset(&req, 0, sizeof(req));
158	  req.type   = cap_type;
159	  req.memory = V4L2_MEMORY_USERPTR;
160	  req.count  = 2;
161	  if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0)
162	    { /* printf("ERROR: CAPTURE REQBUFS: %d\n", errno); */ goto out; }
163	  MARK('4'); /* reqbufs ok */
164	
165	  /* Allocate capture buffer and queue it on the CAPTURE queue */
166	
167	  capbuf = memalign(64, CAP_SIZE);
168	  if (!capbuf)
169	    { /* printf("ERROR: memalign capture\n"); */ goto out; }
170	
171	  memset(&buf, 0, sizeof(buf));
172	  buf.type      = cap_type;
173	  buf.memory    = V4L2_MEMORY_USERPTR;
174	  buf.index     = 0;
175	  buf.m.userptr = (unsigned long)capbuf;
176	  buf.length    = CAP_SIZE;
177	  if (xioctl(fd, VIDIOC_QBUF, &buf) < 0)
178	    { /* printf("ERROR: CAPTURE QBUF: %d\n", errno); */ goto out; }
179	  MARK('5'); /* capture qbuf ok */
180	
181	  /* Queue input frame on OUTPUT queue */
182	
183	  memset(&buf, 0, sizeof(buf));
184	  buf.type      = out_type;
185	  buf.memory    = V4L2_MEMORY_USERPTR;
186	  buf.index     = 0;
187	  buf.m.userptr = (unsigned long)inbuf;
188	  buf.length    = OUT_SIZE;
189	  buf.bytesused = OUT_SIZE;
190	  if (xioctl(fd, VIDIOC_QBUF, &buf) < 0)
191	    { /* printf("ERROR: OUTPUT QBUF: %d\n", errno); */ goto out; }
192	  MARK('6'); /* output qbuf ok */
193	
194	  /* Start both queues */
195	
196	  if (xioctl(fd, VIDIOC_STREAMON, &out_type) < 0)
197	    { /* printf("ERROR: OUTPUT STREAMON: %d\n", errno); */ goto out; }
198	  if (xioctl(fd, VIDIOC_STREAMON, &cap_type) < 0)
199	    { /* printf("ERROR: CAPTURE STREAMON: %d\n", errno); */ goto out; }
200	  MARK('7'); /* streaming */
201	  /* printf("  streaming...\n"); */
202	  /* fflush(stdout); */
203	
204	  /* Wait for the encoded frame to be ready (DQBUF returns EAGAIN until then) */
205	
206	  {
207	    struct pollfd pfd;
208	    int pret;
209	
210	    pfd.fd     = fd;
211	    pfd.events = POLLIN;
212	    pfd.revents = 0;
213	    for (int tries = 0; tries < 50; tries++)
214	      {
215	        pret = poll(&pfd, 1, 100);
216	        if (pret < 0)
217	          { /* printf("ERROR: poll: %d\n", errno); */ goto out; }
218	        if (pret > 0 && (pfd.revents & POLLIN))
219	          {
220	            MARK('8'); /* poll ready */
221	            break;
222	          }
223	      }
224	
225	    if (pret <= 0 || !(pfd.revents & POLLIN))
226	      {
227	        /* printf("ERROR: timeout waiting for encoded frame\n"); */
228	        goto out;
229	      }
230	  }
231	
232	  /* Dequeue encoded JPEG */
233	
234	  memset(&buf, 0, sizeof(buf));
235	  buf.type   = cap_type;
236	  buf.memory = V4L2_MEMORY_USERPTR;
237	  if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0)
238	    { /* printf("ERROR: CAPTURE DQBUF: %d\n", errno); */ goto out; }
239	  /* printf("  encoded frame %u: %u bytes\n",
240	         (unsigned int)buf.index, (unsigned int)buf.bytesused); */

1	/****************************************************************************
2	 * arch/risc-v/src/common/espressif/esp_jpeg_enc.c
3	 * ESP32-P4 Hardware JPEG Encoder in V4L2 M2M framework
4	 *
5	 * Uses the esp-hal-3rdparty JPEG HAL (jpeg_new_encoder_engine /
6	 * jpeg_encoder_process / jpeg_del_encoder_engine) to turn one RGB565
7	 * frame queued on the OUTPUT queue into a JPEG bitstream on the CAPTURE
8	 * queue.  Encoding is triggered from the *_available() callbacks, which
9	 * the v4l2_m2m core invokes after every VIDIOC_QBUF.
10	 *
11	 * SPDX-License-Identifier: Apache-2.0
12	 ****************************************************************************/
13	
14	#include <nuttx/config.h>
15	#include <stdio.h>
16	#include <string.h>
17	#include <debug.h>
18	#include <errno.h>
19	#include <sys/param.h>
20	
21	#include <nuttx/kmalloc.h>
22	#include <nuttx/mutex.h>
23	#include <nuttx/video/v4l2_m2m.h>
24	
25	#include "driver/jpeg_encode.h"
26	
27	/* Polled markers use the USB-Serial-JTAG TX FIFO directly.  To avoid a race
28	 * with the console ISR (which flushes the printf xmit buffer via the same
29	 * FIFO + txfifo_flush and drops concurrently-written bytes), the console TX
30	 * interrupt is masked for the duration of jpeg_new_encoder_engine so the
31	 * markers own the FIFO exclusively.  See esp_usbserial_write()/esp_send().
32	 */
33	#include "esp_usbserial.h"
34	
35	#define JPEG_DEF_WIDTH    1024
36	#define JPEG_DEF_HEIGHT   600
37	#define JPEG_MAX_BUF      6
38	#define JPEG_QUALITY      80
39	
40	struct esp_jpeg_dev_s
41	{
42	  struct v4l2_format  out_fmt;
43	  struct v4l2_format  cap_fmt;
44	  jpeg_encoder_handle_t engine;
45	  FAR void *cookie;              /* v4l2_m2m codec_file_t, for codec_*_buf() */
46	  size_t  encoded;
47	};
48	
49	static int jpeg_cap_enum_fmt(FAR void *p, FAR struct v4l2_fmtdesc *f)
50	{ if (f->index > 0) return -EINVAL; f->pixelformat = V4L2_PIX_FMT_JPEG;
51	  f->type = V4L2_BUF_TYPE_VIDEO_CAPTURE; return OK; }
52	
53	static int jpeg_out_enum_fmt(FAR void *p, FAR struct v4l2_fmtdesc *f)
54	{ if (f->index > 0) return -EINVAL; f->pixelformat = V4L2_PIX_FMT_RGB565;
55	  f->type = V4L2_BUF_TYPE_VIDEO_OUTPUT; return OK; }
56	
57	static int jpeg_cap_g_fmt(FAR void *p, FAR struct v4l2_format *f)
58	{ memcpy(f, &((struct esp_jpeg_dev_s *)p)->cap_fmt, sizeof(*f)); return OK; }
59	
60	static int jpeg_out_g_fmt(FAR void *p, FAR struct v4l2_format *f)
61	{ memcpy(f, &((struct esp_jpeg_dev_s *)p)->out_fmt, sizeof(*f)); return OK; }
62	
63	static int jpeg_cap_s_fmt(FAR void *p, FAR struct v4l2_format *f)
64	{ struct esp_jpeg_dev_s *d = p;
65	  if (f->fmt.pix.pixelformat != V4L2_PIX_FMT_JPEG) return -EINVAL;
66	  f->fmt.pix.width  = d->out_fmt.fmt.pix.width;
67	  f->fmt.pix.height = d->out_fmt.fmt.pix.height;
68	  f->fmt.pix.sizeimage = d->out_fmt.fmt.pix.sizeimage;
69	  memcpy(&d->cap_fmt, f, sizeof(*f)); return OK; }
70	
71	static int jpeg_out_s_fmt(FAR void *p, FAR struct v4l2_format *f)
72	{ struct esp_jpeg_dev_s *d = p;
73	  if (f->fmt.pix.pixelformat != V4L2_PIX_FMT_RGB565) return -EINVAL;
74	  f->fmt.pix.width  = CLAMP(f->fmt.pix.width,  16, 1024);
75	  f->fmt.pix.height = CLAMP(f->fmt.pix.height, 16, 768);
76	  f->fmt.pix.sizeimage = f->fmt.pix.width * f->fmt.pix.height * 2;
77	  memcpy(&d->out_fmt, f, sizeof(*f)); return OK; }
78	
79	static size_t jpeg_cap_bufsize(FAR void *p)
80	{ return ((struct esp_jpeg_dev_s *)p)->out_fmt.fmt.pix.sizeimage; }
81	
82	static size_t jpeg_out_bufsize(FAR void *p)
83	{ return ((struct esp_jpeg_dev_s *)p)->out_fmt.fmt.pix.sizeimage; }
84	
85	static size_t jpeg_cap_bufcnt(FAR void *p) { return 4; }
86	static size_t jpeg_out_bufcnt(FAR void *p) { return 4; }
87	
88	static FAR void *jpeg_alloc(FAR void *p, size_t sz) { return kmm_malloc(sz); }
89	static void jpeg_free(FAR void *p, FAR void *a) { kmm_free(a); }
90	
91	/****************************************************************************
92	 * Name: jpeg_encode_one
93	 *
94	 * Description:
95	 *   Pull one RGB565 frame from the OUTPUT queue, encode it with the JPEG
96	 *   HAL, and push the resulting bitstream into the CAPTURE queue.
97	 *   Safe to call from either *_available() callback (the v4l2_m2m core
98	 *   calls these after each QBUF on the respective queue); no-ops when a
99	 *   frame or a capture buffer is missing.
100	 *
101	 ****************************************************************************/
102	
103	static int jpeg_encode_one(FAR void *priv)
104	{
105	  struct esp_jpeg_dev_s *d = priv;
106	  FAR struct v4l2_buffer *in;
107	  FAR struct v4l2_buffer *cap;
108	  jpeg_encode_cfg_t cfg;
109	  uint32_t out_sz = 0;
110	  esp_err_t err;
111	
112	  if (d->engine == NULL)
113	    {
114	      return 0;
115	    }
116	
117	  in = codec_output_get_buf(d->cookie);
118	  if (in == NULL)
119	    {
120	      return 0;
121	    }
122	
123	  dbg_putc('p');               /* jpeg_encode_one: about to get capture buf */
124	  cap = codec_capture_get_buf(d->cookie);
125	  if (cap == NULL)
126	    {
127	      codec_output_put_buf(d->cookie, in);
128	      return 0;
129	    }
130	
131	  memset(&cfg, 0, sizeof(cfg));
132	  cfg.width         = d->out_fmt.fmt.pix.width;
133	  cfg.height        = d->out_fmt.fmt.pix.height;
134	  cfg.src_type      = JPEG_ENCODE_IN_FORMAT_RGB565;
135	  cfg.sub_sample    = JPEG_DOWN_SAMPLING_YUV420;
136	  cfg.image_quality = JPEG_QUALITY;
137	
138	  dbg_putc('q');               /* about to call jpeg_encoder_process */
139	  err = jpeg_encoder_process(d->engine, &cfg,
140	                             (FAR const uint8_t *)in->m.vaddr,
141	                             in->length,
142	                             (FAR uint8_t *)cap->m.vaddr,
143	                             cap->length,
144	                             &out_sz);
145	  dbg_putc('r');               /* jpeg_encoder_process returned */
146	  if (err != ESP_OK)
147	    {
148	      vwarn("jpeg encode failed: %d\n", err);
149	      cap->bytesused = 0;
150	      codec_capture_put_buf(d->cookie, cap);
151	      codec_output_put_buf(d->cookie, in);
152	      return 0;
153	    }
154	
155	  vinfo("encoded %u x %u RGB565 -> %u bytes JPEG\n",
156	        cfg.width, cfg.height, (unsigned int)out_sz);
157	  cap->bytesused = out_sz;
158	  d->encoded = out_sz;
159	  codec_capture_put_buf(d->cookie, cap);
160	  codec_output_put_buf(d->cookie, in);
161	  return 0;
162	}
163	
164	static int jpeg_open(FAR void *cookie, FAR void **priv)
165	{
