      uint32_t v = w6[j];
      dbg_putc(':');
      dbg_putc(hex[(v >> 28) & 0xF]); dbg_putc(hex[(v >> 24) & 0xF]);
      dbg_putc(hex[(v >> 20) & 0xF]); dbg_putc(hex[(v >> 16) & 0xF]);
      dbg_putc(hex[(v >> 12) & 0xF]); dbg_putc(hex[(v >>  8) & 0xF]);
