171	{
172	  struct esp_jpeg_dev_s *d;
173	  dbg_putc('V');               /* jpeg_open entered */
174	  d = kmm_zalloc(sizeof(*d));
175	  jpeg_encode_engine_cfg_t ecfg;
176	  esp_err_t err;
177	
178	  if (d == NULL)
179	    {
180	      return -ENOMEM;
181	    }
182	
183	  d->cookie = cookie;
184	  d->out_fmt.type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
185	  d->out_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
186	  d->out_fmt.fmt.pix.width  = JPEG_DEF_WIDTH;
187	  d->out_fmt.fmt.pix.height = JPEG_DEF_HEIGHT;
188	  d->out_fmt.fmt.pix.sizeimage = JPEG_DEF_WIDTH * JPEG_DEF_HEIGHT * 2;
189	  d->cap_fmt = d->out_fmt;
190	  d->cap_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
191	
192	  /* Create the ESP-HAL JPEG encoder engine.  One engine per open file;
193	   * the HAL reference-counts the underlying codec handle internally. */
194	
195	  memset(&ecfg, 0, sizeof(ecfg));
196	  ecfg.intr_priority = 0;   /* driver picks a default */
197	  ecfg.timeout_ms    = 1000; /* 1 s is well above a 1024x600 encode */
198	
199	  dbg_putc('W');               /* about to call jpeg_new_encoder_engine */
200	  /* ARM the dispatch storm latch right here: zero the counter/latch so the
201	   * latch captures the FIRST trap of THIS engine's storm (not boot leftovers).
202	   * 0x5010ffe4=cnt, 0x5010ffe8=mcause latch, 0x5010ffec=resolved irq. */
203	  *((volatile uint32_t *)0x5010ffe4) = 0;
204	  *((volatile uint32_t *)0x5010ffe8) = 0;
205	  *((volatile uint32_t *)0x5010ffec) = 0;
206	  *((volatile uint32_t *)0x5010fe40) = 0;   /* mcause ring head */
207	  err = jpeg_new_encoder_engine(&ecfg, &d->engine);
